import json,hashlib,shutil,pathlib,copy
base=pathlib.Path('research/quantum-prerequisites-4-2026-10-15-owner/authoring-gate-escalation'); out=base/'coverage'; run='quantum-prerequisites-4-2026-10-15'
def sha(p): return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def row(name,disposition,item=None,**kw): return dict(name=name,disposition=disposition,**({'item':item} if item else {}),**kw)
def bsource(src,locator,contents,reading):
 s=copy.deepcopy(src); s['locator']=locator; s['contents']=contents; s['reading_verification']=reading; s['fetch_evidence_origin']=f'Existing genuine A-page record in research/{run}-batch-'+('1' if 'Axler' in s['title'] or 'Hunter' in s['title'] else '3' if 'Lebl' in s['title'] or 'Lang' in s['title'] else '4')+'.coverage.json; identical source URL and historical stamp, reused as document evidence, not a new retrieval or reading stamp.'; return s
patches=[]
for batch in [1,3,4]:
 name=f'{run}-batch-{batch}.coverage.json'; old=base/name; live=pathlib.Path('research')/name
 assert old.read_bytes()==live.read_bytes()
 (out/'before').mkdir(exist_ok=True); shutil.copyfile(old,out/'before'/name)
 d=json.loads(old.read_text()); a=d['pages'][0]; sources=a['sources']
 for s in sources:
  if s.get('kind')=='book': s['kind']='textbook'
  if s.get('kind')=='survey article': s['kind']='survey'
 if batch==1:
  ex='ex-pointwise-extended-real-function-product-cases'
  ax=bsource(sources[0], 'Section 3A, printed p. 74, the zero-times-infinity convention immediately before Definition 3.2; surrounding Definitions 3.1–3.3 on p. 74 inspected.', [row('Section 3A convention: 0·∞ and ∞·0 are interpreted as zero','inline',ex, support='The positive-infinity zero rows x1 and x3 illustrate this integration convention through the locally proved A definition. The source does not state the ten-point table or its signed extension; zero at negative infinity, the four signed-infinite rows, and finite arithmetic are checked from def-measurable-pointwise-extended-real-product, ultimately def-extended-reals, in verification steps 1.1–1.3.')], 'Read the complete relevant p. 74 from the locally retained full-source extraction. The convention precedes the lower-Lebesgue-sum definition and concerns nonnegative integration; the B table is an original local example, not an example attributed to Axler.')
  hu=bsource(sources[1], 'Section 3.2, printed p. 36 (PDF p. 40), paragraph immediately after the proof of Proposition 3.6; complete pp. 34–36 inspected for context.', [row('Extended-real product definedness excludes a zero paired with ±∞','already-published','def-extended-reals', support='Hunter explicitly excludes precisely these scalar value pairs. The published supplier retains that partial-scalar boundary; the A definition adds a separately typed total function convention, and the B example tests all four additional zero values. No measurability conclusion of Proposition 3.6 is claimed for this example.')], 'Read Section 3.2 in the local full-source extraction. The discussion after Proposition 3.6 says the extended-real product must be well-defined and excludes simultaneous 0 and ±∞. This is comparison/context via the published scalar supplier, not a proof by Hunter of the total convention or the ten-point table.')
  d['pages'][1]['sources']=[ax,hu]
  d['pages'][1]['canonical']=[row('Original ten-point worked example: four ordered zero-infinity pairs, four signed-infinite pairs, and two finite pairs','included',ex, support='Not a source heading or source example. Verification steps 1.1–1.3 apply the exact local A definition to every row; step 2.1 assembles the output tuple. Axler supplies the nonnegative zero-convention motivation and Hunter the contrasting scalar-definedness boundary, not the exact table.')]
 if batch==3:
  sh=sources[-1]['contents'][0]
  sh['disposition']='already-published'; sh['item']='thm-rectifiable-iff-coordinate-functions-have-bounded-variation'
  sh['reason']='The Shastri full text remains inaccessible and unread here; retain the six genuine failures and dropped source_resolution. The named general R^n coordinate-BV criterion is already proved in published thm-rectifiable-iff-coordinate-functions-have-bounded-variation. Its n=2 specialization is actually used by thm-complex-path-coordinate-length-rectifiability-and-piecewise-c1-speed after the coordinate isometry. Independently inspected Ahlfors Chapter 4 §1.2, printed pp.104–105 (PDF pp.120–121), states the complex coordinate-BV equivalence. No claim or local proof is dropped, and no direct Shastri reading is claimed.'
  sh['support']='The published supplier proves |z_j|≤||z||₂≤Σ|z_j| termwise on each partition and then takes suprema, including the singleton case. The current complex theorem identifies complex/Euclidean chord sums before using that supplier. This preserves the full criterion without treating the inaccessible source excerpt as a proof premise.'
  sources[2]['locator']='Chapter 4, §1.2, printed pp. 104–105 (PDF pp. 120–121), rectifiable arcs and coordinate bounded variation.'
  ex='ex-complex-coordinate-and-path-transport'
  le=bsource(sources[0], 'Chapter 1 §1.1.1, printed pp. 9–10, coordinate arithmetic; Chapter 2 §2.1.2, printed p. 27, real differentiability remainder paragraph preceding the Cauchy–Riemann characterization.', [row('Complex numbers as the plane and coordinate arithmetic','inline',ex,support='Specialized through A-page scalar/isometry transport to verification steps 1.1–1.2: coordinates, real affine combination, distance sqrt(13), and ball correspondence. The chosen numbers and ball are original local data.'),row('Real differentiability as a real 2-by-2 matrix with o(|h|) remainder','inline',ex,support='The general real-differentiability paragraph supports the coordinate viewpoint. Step 1.3 proves directly that conjugation is real-linear with zero remainder and diagonal matrix (1,-1); it does not claim complex differentiability or import the subsequent Cauchy–Riemann criterion.')], 'Read the full coordinate subsection and the real-remainder paragraph in the locally retained complete book extraction. These source results are specialized by the local A theorems; no assertion that the exact numerical example appears in Lebl is made.')
  la=bsource(sources[3], 'Section 1.1, printed pp. 1–2: metric chord-supremum definition, continuous surjective weakly monotone reparametrization paragraph, and C1 speed-integral paragraph.', [row('Metric-space chord-supremum length and rectifiability','inline',ex,support='The definition is specialized through the local complex-path definition. The finite path and singleton are checked locally; the original bounded triangular-spike path has partition sums 2H_N, so it is nonrectifiable by this definition.'),row('Length invariance under continuous surjective nondecreasing or nonincreasing reparametrization','inline',ex,support='Through the local A theorem, step 3.1 applies the general result to the explicitly checked reversal phi and pause map psi. These maps and the path are original example data.'),row('Euclidean C1 speed-integral length formula','inline',ex,support='Via the locally proved piecewise-C1 supplier, step 2.1 uses three affine/constant pieces with speeds 1,1,0 and total length 2. The source C1 formula supports each piece; finite subdivision and corner handling are supplied locally.')], 'Read the exact definition, reparametrization paragraph, and speed-integral paragraph from the retained complete lecture notes. These are independent of Lebl coordinate arithmetic. No source attribution is made for the original path, pause/reversal maps, singleton convention, or harmonic-spike construction.')
  d['pages'].append(dict(page='complex-coordinate-and-path-transport-examples',kind='B',order=358.11,sources=[le,la],canonical=[row('Original bounded continuous triangular-spike path with unbounded polygonal sums','included',ex,support='Original local construction, not a claimed source example. Steps 1.6–1.8 prove well-definedness, boundedness, continuity, and partition sums 2H_N. Steps 1.9, 2.2, and 3.2 give the doubling-block harmonic lower bound; step 4.1 applies the chord-supremum definition to conclude nonrectifiability.')]))
 if batch==4:
  ex='ex-complex-line-realification-basis-in-c2'
  ko=bsource(sources[0], 'PDF p. 1 Definition 1.1 and induced norm metric; PDF p. 2 Example 1.2(1), the finite-dimensional p-norm formula with K=C, n=2, p=1.', [row('Definition 1.1: real/complex norm axioms and induced norm metric','inline',ex,support='Step 1.1 checks the complex line is a subspace with restricted norm; step 2.1 invokes the A lemma for the identical restricted real metric. The metric restriction is proved locally, rather than attributed as a separate theorem to the notes.'),row('Example 1.2(1): finite-dimensional coordinate p-norms over R or C','included',ex,support='The example norm N(z1,z2)=|z1|+|z2| is exactly the K=C,n=2,p=1 specialization. The local supplier lem-complex-coordinate-l1-is-a-norm proves the norm claim. Kochanek does not choose the subspace C(1,i) or state its displayed real basis.')], 'Read the complete locally retained five-page notes, focusing on Definition 1.1, its metric paragraph, and Example 1.2(1). These give the ambient norm and metric conventions for this B example; its subspace and real basis are independently verified locally.')
  su=bsource(sources[1], 'Section 2.1 Linear algebra, PDF p. 5, first three paragraphs: scalar restriction, finite complex basis to interleaved real basis, and complex subspace implies real subspace.', [row('Realification by restricting complex scalars to R','inline',ex,support='Applied through the local A lemma to the complex line W after closure is proved in step 1.1; the underlying set/addition are unchanged.'),row('A finite complex basis f1,...,fn induces the real basis f1,if1,...,fn,ifn','included',ex,support='The general n=1 conversion motivates (b,ib). The example chooses b=(1,i) itself, computes ib=(i,-1), and proves real independence in step 1.2 and real spanning in step 2.2, then ordered-basis validity in step 3.1. The exact line and ordered pair are not attributed to the survey.'),row('A complex linear subspace remains a real linear subspace','inline',ex,support='Specialized to W=C(1,i) through the A lemma in step 2.1. The notes and the survey are independent treatments with different roles: coordinate norm/metric versus scalar restriction and basis conversion.')], 'Downloaded the complete 80-page PDF from the original exact URL for this source reading; its SHA256 begins 344e904a2fe97d9f, identical to the genuine historical fetch stamp. Read title metadata and the complete §2.1. Only the first three paragraphs are harvested for this B example; subsequent odd-dimensional-matrix and triangularization discussions do not supply its proof.')
  su['cached_pdf']=str(out/'sources/moslehian-real-complex.pdf');su['cached_text']=str(out/'sources/moslehian-real-complex.txt')
  d['pages'][1]['sources']=[ko,su]
  d['pages'][1]['canonical']=[row('Original complex line W=C(1,i) in coordinate-l1 C2 and ordered real basis ((1,i),(i,-1))','included',ex,support='The ambient norm is a source specialization; the chosen line and its explicit calculation are original. The local proof checks closure, real independence, metric restriction, spanning, and ordered-basis injectivity without relying on an assertion that this precise example occurs in either source.')]
 target=out/name;target.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
 manifest=pathlib.Path('research')/name.replace('.coverage.json','.pages.json');shutil.copyfile(manifest,out/manifest.name)
 patches.append(dict(target=str(live),before_file=str(out/'before'/name),before_sha256=sha(live),proposed_file=str(target),proposed_sha256=sha(target),context_manifest=str(out/manifest.name),context_manifest_sha256=sha(manifest)))
(out/'patch-manifest.json').write_text(json.dumps(dict(version=1,kind='proposed-coverage-metadata-repair',run=run,apply_policy='Compare exact live bytes to before_sha256, then copy proposed bytes. No other files are proposed for integration.',files=patches),indent=2)+'\n')
print(json.dumps(patches,indent=2))
